import {formatPlayTime,playTimeStorageNote} from './play-time.js?v=0.346.0';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const google=`<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path fill="#4285F4" d="M21.6 12.2c0-.7-.1-1.4-.2-2.1H12v4h5.4a4.6 4.6 0 0 1-2 3v2.5h3.3c1.9-1.8 2.9-4.3 2.9-7.4Z"/><path fill="#34A853" d="M12 22c2.7 0 5-1 6.7-2.4l-3.3-2.6c-.9.6-2 1-3.4 1-2.6 0-4.8-1.7-5.6-4H3v2.6A10 10 0 0 0 12 22Z"/><path fill="#FBBC05" d="M6.4 14a6 6 0 0 1 0-4V7.4H3a10 10 0 0 0 0 9.2L6.4 14Z"/><path fill="#EA4335" d="M12 6c1.5 0 2.8.5 3.8 1.5l2.8-2.8A9.5 9.5 0 0 0 12 2a10 10 0 0 0-9 5.4L6.4 10c.8-2.3 3-4 5.6-4Z"/></svg>`;
const totals=s=>({decks:s?.decks?.length||0,friends:s?.friends?.length||0});
const counts=s=>{const n=totals(s);return `マイデッキ ${n.decks}件 · 相手デッキ ${n.friends}件`;};
function setupHTML(){return `<section class="account-setup panel"><span class="badge amber">Googleログインは初期設定待ち</span><h2>無料で使うための初期設定</h2><p>Firebaseの無料プラン「Spark」で準備します。請求先の登録や有料プランへの変更は必要ありません。</p><ol><li><a href="https://console.firebase.google.com/" target="_blank" rel="noopener noreferrer">Firebaseコンソール</a>でプロジェクトを作成。Google Analyticsは省略できます。</li><li>「プロジェクトの設定」からウェブアプリ（&lt;/&gt;）を登録し、表示された <code>firebaseConfig</code> の公開設定をこのチャットへ送ります。</li><li>「Authentication」→「始める」→「Google」を有効にし、サポートメールを選択します。</li><li>Authenticationの「設定」→「承認済みドメイン」に <code>duema-deck-lab.jolly-vole-4389.chatgpt.site</code> を追加します。将来の公開先でも、そのドメインを追加します。</li><li>「Firestore Database」で <strong>Standard edition・本番モード・(default)</strong> のデータベースを1つ作ります。「ルール」を<a href="firestore.rules" target="_blank" rel="noopener">このアプリ用のルール</a>に置き換えて公開します。初期のテストモードは使いません。</li></ol><p class="small">送るのはWeb用の <code>apiKey</code>・<code>authDomain</code>・<code>projectId</code>・<code>appId</code> です。サービスアカウントの秘密鍵は不要です。</p><p class="small">無料枠を超えた場合は利用制限がかかります。Blazeへの変更、請求先のリンク、Cloud Functionsの有効化はこの設定には含みません。</p><a class="details-link" href="https://firebase.google.com/docs/projects/billing/firebase-pricing-plans" target="_blank" rel="noopener">Firebaseの公式料金案内 ↗</a></section>`;}
export function accountScreenHTML(state,saved,playTime={}){
 const busy=!!state.busy,user=state.user,ready=state.phase==='signed-out',cloud=state.cloud?.snapshot;let when='';if(state.cloud?.updatedAt){const time=Date.parse(state.cloud.updatedAt);if(Number.isFinite(time))when=new Intl.DateTimeFormat('ja-JP',{dateStyle:'medium',timeStyle:'short'}).format(time);}
 return `<div class="page-head"><div class="page-title"><div class="eyebrow">YOUR ACCOUNT</div><h1>アカウント</h1><p>デッキを保存して、別の端末でも。</p></div><button class="btn" data-action="nav" data-view="decks">デッキへ戻る</button></div><section class="panel account-playtime" aria-labelledby="playtime-title"><div class="account-playtime-head"><span class="account-playtime-icon" aria-hidden="true"><svg width="25" height="25" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/></svg></span><div><h2 id="playtime-title">プレイ時間</h2><span class="small" data-playtime-scope>${playTime.syncPhase&&playTime.syncPhase!=='local'?'アカウントの累計':'このブラウザの累計'}</span></div><button class="details-link" data-action="account-sync-playtime" ${!user||playTime.syncPhase==='syncing'?'disabled':''}>時間を同期</button></div><strong class="account-playtime-value" data-playtime-value>${formatPlayTime(playTime.totalMs)}</strong><p class="small mt16">デッキ作成や対戦など、アプリを表示している時間を記録します。別のタブやアプリを見ている間は停止します。</p><p class="source-note mt8" data-playtime-note>${playTimeStorageNote(playTime.storageOK,playTime.syncPhase)}</p></section><div class="account-layout"><section class="panel account-profile">${user?`<div class="account-identity"><span class="account-avatar">${esc(user.name.slice(0,1))}</span><div><span class="badge green">Googleでログイン中</span><h2>${esc(user.name)}</h2><p>${esc(user.email)}</p></div></div><button class="btn" data-action="account-logout" ${busy?'disabled':''}>ログアウト</button><p class="account-privacy">ログアウト後も、この端末に保存したデッキは残ります。</p>`:`<div class="account-welcome"><span class="account-avatar">${google}</span><h2>いつものGoogleアカウントで</h2><p>初回のログインで登録が完了します。<br>アプリ専用のパスワードは不要です。</p><button class="btn account-google" data-action="account-login" ${!ready||busy?'disabled':''}>${google}${state.busy==='login'?'ログイン画面を開いています…':state.phase==='loading'?'ログイン状態を確認中…':'Googleで登録・ログイン'}</button>${state.homeScreen?'<p class="small mt16">Googleアカウントを選んだら、このアプリに戻ってください。</p>':''}${state.busy==='login'?'<div class="account-login-recovery"><p class="small" role="status">Googleアカウントを選んだ後もこの表示が続く場合は、ログイン状態を確認できます。</p><button class="btn" data-action="account-check-login">ログイン状態を確認</button><button class="btn ghost" data-action="account-cancel-login">ログインをやり直す</button></div>':''}</div>`}<p class="account-privacy">Googleログインでは名前とメールアドレスを利用します。メールの内容やパスワードは取得しません。</p></section><div class="account-storage"><section class="panel account-local"><span class="eyebrow">この端末</span><h2>いまのデッキ</h2><p class="account-counts">${counts(saved)}</p><p class="small">ログインしても、この端末のデッキは自動で書き換わりません。</p></section><section class="panel account-cloud"><span class="eyebrow">アカウントに保存</span><h2>${!user?'Googleログインで使えます':!state.loaded?'保存内容を確認する':cloud?'保存したデッキ':'最初のデッキを保存しよう'}</h2><p class="account-counts">${cloud?counts(cloud):user&&state.loaded?'まだ保存されていません':'別の端末からも取り込めます'}</p>${cloud?`<p class="small">${when?'保存日時 '+esc(when):'保存済み'} · 保存版 ${state.cloud.revision}</p>`:''}<div class="account-actions"><button class="btn primary" data-action="account-save" ${!user||!state.loaded||busy||!(saved.decks.length+saved.friends.length)?'disabled':''}>${state.busy==='save'?'保存しています…':'この端末のデッキを保存'}</button><button class="btn" data-action="account-import" ${!user||!state.loaded||!cloud||busy?'disabled':''}>保存したデッキを取り込む</button>${user?`<button class="details-link" data-action="account-refresh" ${busy?'disabled':''}>${state.busy==='load'?'読込中…':'保存内容を再読込'}</button>`:''}</div><p class="small">「取り込む」はデッキを追加します。同じ名前・構成は重複させず、変更済みのデッキは別のデッキとして残します。</p><p class="source-note">プレイ時間はログイン中に自動同期します。対戦履歴・写真・進行中の対戦は、このデッキ保存には含みません。</p></section></div></div>${state.error?`<div class="notice account-error" role="alert"><p>${esc(state.error)}</p>${/^auth\/[a-z-]{1,80}$/.test(state.errorCode||'')?`<p class="small">エラーコード：${esc(state.errorCode)}</p>`:''}${state.phase==='error'?'<button class="btn" data-action="account-reload-page">アプリを再読込</button>':''}</div>`:''}${state.phase==='unconfigured'?setupHTML():''}<div class="account-next"><strong>友達とオンライン対戦</strong><p>ルームコードを共有して、それぞれ自分のデッキで対戦できます。</p><button class="btn primary" data-action="nav" data-view="online">友達と対戦する</button></div>`;
}
